   481  fz_buffer *
   482  pdf_load_raw_stream_number(fz_context *ctx, pdf_document *doc, int num)
   483  {
   484          fz_stream *stm;
   485          pdf_obj *dict;
   486          int64_t len;
   487          fz_buffer *buf = NULL;
   488          pdf_xref_entry *x;
   489
   490          if (num > 0 && num < pdf_xref_len(ctx, doc))
   491          {
   492                  x = pdf_get_xref_entry_no_null(ctx, doc, num);
   493                  if (x->stm_buf)
   494                          return fz_keep_buffer(ctx, x->stm_buf);
   495          }
   496
   497          dict = pdf_load_object(ctx, doc, num);
   498
   499          fz_try(ctx)
   500                  len = pdf_dict_get_int64(ctx, dict, PDF_NAME(Length));
   501          fz_always(ctx)
   502                  pdf_drop_obj(ctx, dict);
   503          fz_catch(ctx)
   504                  fz_rethrow(ctx);
   505
   506          stm = pdf_open_raw_stream_number(ctx, doc, num);
   507
   508          if (len < 0)
   509                  len = 1024;
   510
   511          fz_try(ctx)
   512                  buf = fz_read_all(ctx, stm, (size_t)len);
   513          fz_always(ctx)
   514                  fz_drop_stream(ctx, stm);
   515          fz_catch(ctx)
   516                  fz_rethrow(ctx);
   517
   518          return buf;
   519  }
