  3323  static void fmt_obj(fz_context *ctx, struct fmt *fmt, pdf_obj *obj)
  3324  {
  3325          char buf[256];
  3326
  3327          if (obj == PDF_NULL)
  3328                  fmt_puts(ctx, fmt, "null");
  3329          else if (obj == PDF_TRUE)
  3330                  fmt_puts(ctx, fmt, "true");
  3331          else if (obj == PDF_FALSE)
  3332                  fmt_puts(ctx, fmt, "false");
  3333          else if (pdf_is_indirect(ctx, obj))
  3334          {
  3335                  fz_snprintf(buf, sizeof buf, "%d %d R", pdf_to_num(ctx, obj), pdf_to_gen(ctx, obj));
  3336                  fmt_puts(ctx, fmt, buf);
  3337          }
  3338          else if (pdf_is_int(ctx, obj))
  3339          {
  3340                  fz_snprintf(buf, sizeof buf, "%d", pdf_to_int(ctx, obj));
  3341                  fmt_puts(ctx, fmt, buf);
  3342          }
  3343          else if (pdf_is_real(ctx, obj))
  3344          {
  3345                  fz_snprintf(buf, sizeof buf, "%g", pdf_to_real(ctx, obj));
  3346                  fmt_puts(ctx, fmt, buf);
  3347          }
  3348          else if (pdf_is_string(ctx, obj))
  3349          {
  3350                  unsigned char *str = (unsigned char *)pdf_to_str_buf(ctx, obj);
  3351                  if (fmt->crypt
  3352                          || (fmt->ascii && is_binary_string(ctx, obj))
  3353                          || (str[0]==0xff && str[1]==0xfe)
  3354                          || (str[0]==0xfe && str[1] == 0xff)
  3355                          || is_longer_than_hex(ctx, obj)
  3356                          )
  3357                          fmt_hex(ctx, fmt, obj);
  3358                  else
  3359                          fmt_str(ctx, fmt, obj);
  3360          }
  3361          else if (pdf_is_name(ctx, obj))
  3362                  fmt_name(ctx, fmt, obj);
  3363          else if (pdf_is_array(ctx, obj))
  3364                  fmt_array(ctx, fmt, obj);
  3365          else if (pdf_is_dict(ctx, obj))
  3366                  fmt_dict(ctx, fmt, obj);
  3367          else
  3368                  fmt_puts(ctx, fmt, "<unknown object>");
  3369  }
